    template <class... Ts>                                                                         \
    CUB_RUNTIME_FUNCTION cudaError_t operator()(std::uint8_t *d_temp_storage,                      \
                                                std::size_t &temp_storage_bytes,                   \
                                                Ts... args)                                        \
    {                                                                                              \
      return API(d_temp_storage, temp_storage_bytes, args...);                                     \
    }                                                                                              \
  };                                                                                               

